# AeroSim vehicle kit, core helpers (Blender 4.2, headless bpy).
# Frame used while modelling: metres, +X is the vehicle's right, +Y its front, +Z up, origin on the ground in the middle of
# the length. The glTF exporter turns Blender +Y into glTF -Z, so in Godot the front is -Z, up +Y, right +X (the batch 6
# convention). Everything here is regenerated by build_vehicles.py; nothing is hand edited.
import bpy, bmesh, math
from mathutils import Vector, Matrix
from mathutils.bvhtree import BVHTree

V = Vector

# ------------------------------------------------------------------ materials
# One shared material per slot name. The slot names are the contract with the game (game/vehicle_assets.gd swaps in the
# vehicle shaders by these names), so keep them stable. Factors here are the stand-alone look of the .glb file.
