def material(name):
    m = bpy.data.materials.get(name)
    if m is not None:
        return m
    col, metal, rough, ex = MAT_DEFS[name]
    m = bpy.data.materials.new(name)
    m.use_nodes = True
    bs = m.node_tree.nodes.get("Principled BSDF")
    bs.inputs["Base Color"].default_value = (col[0], col[1], col[2], 1.0)
    bs.inputs["Metallic"].default_value = metal
    bs.inputs["Roughness"].default_value = rough
    if ex.get("coat"):
        bs.inputs["Coat Weight"].default_value = ex["coat"]
        bs.inputs["Coat Roughness"].default_value = 0.03
    if ex.get("blend") or col[3] < 1.0:
        bs.inputs["Alpha"].default_value = col[3]
        try:
            m.surface_render_method = 'BLENDED'
        except Exception:
            pass
        try:
            m.blend_method = 'BLEND'
        except Exception:
            pass
    if name.startswith("lamp_") or name.startswith("lightbar"):
        bs.inputs["Emission Color"].default_value = (col[0], col[1], col[2], 1.0)
        bs.inputs["Emission Strength"].default_value = 0.0
    m.diffuse_color = (col[0], col[1], col[2], col[3])
    return m


def set_material_colour(name, rgb):
    m = material(name)
    bs = m.node_tree.nodes.get("Principled BSDF")
    bs.inputs["Base Color"].default_value = (rgb[0], rgb[1], rgb[2], 1.0)
    m.diffuse_color = (rgb[0], rgb[1], rgb[2], 1.0)


def srgb_to_lin(c):
    return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4


# ------------------------------------------------------------------ parts
class Part:
    """A bmesh being built, with a material name per face, a bone, and a level-of-detail mask."""

    def __init__(self, name, bone="body"):
        self.name = name
        self.bone = bone
        self.bm = bmesh.new()
        self.mats = []          # material names, index = face material_index
        self.sharp_angle = 35.0

    def mi(self, mat):
        if mat not in self.mats:
            self.mats.append(mat)
        return self.mats.index(mat)

    def add_bm(self, other_bm, mat=None, xf=None, keep_mats=None):
        """Append another bmesh (all faces get `mat`, or keep_mats maps its material indices to names)."""
        vmap = {}
        other_bm.verts.index_update()
        for v in other_bm.verts:
            co = v.co.copy()
            if xf is not None:
                co = xf @ co
            vmap[v.index] = self.bm.verts.new(co)
        for f in other_bm.faces:
            try:
                nf = self.bm.faces.new([vmap[v.index] for v in f.verts])
            except ValueError:
                continue
            if keep_mats is not None:
                nf.material_index = self.mi(keep_mats[f.material_index])
            else:
                nf.material_index = self.mi(mat)
            nf.smooth = f.smooth
        return self

    def face(self, pts, mat, smooth=True):
        vs = [self.bm.verts.new(V(p)) for p in pts]
        f = self.bm.faces.new(vs)
        f.material_index = self.mi(mat)
        f.smooth = smooth
        return f

    def to_object(self, coll=None):
        me = bpy.data.meshes.new(self.name)
        bmesh.ops.remove_doubles(self.bm, verts=self.bm.verts, dist=1e-6)
        self.bm.normal_update()
        self.bm.to_mesh(me)
        for m in self.mats:
            me.materials.append(material(m))
        ob = bpy.data.objects.new(self.name, me)
        (coll or bpy.context.scene.collection).objects.link(ob)
        ob["bone"] = self.bone
        if self.sharp_angle is not None:
            try:
                me.set_sharp_from_angle(angle=math.radians(self.sharp_angle))
            except Exception:
                pass
        return ob


# ------------------------------------------------------------------ primitive builders (return a fresh bmesh)
def bm_box(size, centre=(0, 0, 0)):
    bm = bmesh.new()
    bmesh.ops.create_cube(bm, size=1.0)
    for v in bm.verts:
        v.co = V((v.co.x * size[0] + centre[0], v.co.y * size[1] + centre[1], v.co.z * size[2] + centre[2]))
    for f in bm.faces:
        f.smooth = False
    return bm


def bm_rbox(size, radius, segs=2, centre=(0, 0, 0)):
    """A box with rounded edges (bevelled)."""
    bm = bm_box(size, centre)
    r = min(radius, min(size) * 0.49)
    if r > 1e-4 and segs > 0:
        bmesh.ops.bevel(bm, geom=list(bm.edges) + list(bm.verts), offset=r, segments=segs, profile=0.5, affect='EDGES',
                        clamp_overlap=True)
    for f in bm.faces:
        f.smooth = True
    return bm


def bm_cyl(r0, r1, length, segs=16, axis='Z', centre=(0, 0, 0), caps=True, smooth=True):
    bm = bmesh.new()
    bmesh.ops.create_cone(bm, cap_ends=caps, cap_tris=False, segments=segs, radius1=r0, radius2=r1, depth=length)
    rot = {'Z': Matrix.Identity(4), 'X': Matrix.Rotation(math.pi / 2, 4, 'Y'), 'Y': Matrix.Rotation(-math.pi / 2, 4, 'X')}[axis]
    bmesh.ops.transform(bm, matrix=Matrix.Translation(V(centre)) @ rot, verts=bm.verts)
    for f in bm.faces:
        f.smooth = smooth and len(f.verts) == 4
    return bm


def bm_tube(a, b, r, segs=8, caps=True):
    """A round bar from a to b."""
    a = V(a); b = V(b)
    d = b - a
    L = d.length
    bm = bm_cyl(r, r, L, segs, 'Z', (0, 0, 0), caps)
    q = V((0, 0, 1)).rotation_difference(d.normalized())
    bmesh.ops.transform(bm, matrix=Matrix.Translation((a + b) * 0.5) @ q.to_matrix().to_4x4(), verts=bm.verts)
    return bm


def bm_lathe(profile, segs, axis='X', centre=(0, 0, 0), a0=0.0, a1=2 * math.pi, closed=True, smooth=True):
    """Turn a profile [(radius, axial)] about an axis. Faces have smooth set; caller assigns materials by ring index via
    the returned list of face rings (one list per profile segment)."""
    bm = bmesh.new()
    rings = []
    n = segs if closed else segs + 1
    for k in range(n):
        t = a0 + (a1 - a0) * k / segs
        ring = []
        for (rad, ax) in profile:
            c, s = math.cos(t) * rad, math.sin(t) * rad
            if axis == 'X':
                p = V((ax, c, s))
            elif axis == 'Y':
                p = V((c, ax, s))
            else:
                p = V((c, s, ax))
            ring.append(bm.verts.new(p + V(centre)))
        rings.append(ring)
    seg_faces = [[] for _ in range(len(profile) - 1)]
    for k in range(segs):
        r0 = rings[k]; r1 = rings[(k + 1) % n] if closed else rings[k + 1]
        for i in range(len(profile) - 1):
            vs = [r0[i], r0[i + 1], r1[i + 1], r1[i]]
            if len(set(vs)) < 3:
                continue
            try:
                f = bm.faces.new(vs)
            except ValueError:
                continue
            f.smooth = smooth
            seg_faces[i].append(f)
    bmesh.ops.remove_doubles(bm, verts=bm.verts, dist=1e-7)
    if closed and len(profile) > 2 and tuple(profile[0]) == tuple(profile[-1]):
        bmesh.ops.recalc_face_normals(bm, faces=bm.faces)     # a closed section turned full circle: a solid, face it outward
    return bm, seg_faces


def bm_sweep(section, path, closed_section=True, up=(0, 0, 1)):
    """Sweep a 2D section [(u, v)] along a 3D path. u is along the side vector, v along the 'up' normal."""
    bm = bmesh.new()
    path = [V(p) for p in path]
    up = V(up)
    rings = []
    for i, p in enumerate(path):
        t = (path[min(i + 1, len(path) - 1)] - path[max(i - 1, 0)]).normalized()
        side = t.cross(up)
        if side.length < 1e-6:
            side = t.cross(V((1, 0, 0)))
        side.normalize()
        nrm = side.cross(t).normalized()
        rings.append([bm.verts.new(p + side * u + nrm * v) for (u, v) in section])
    ns = len(section)
    for i in range(len(path) - 1):
        for j in range(ns if closed_section else ns - 1):
            a, b = rings[i][j], rings[i][(j + 1) % ns]
            c, d = rings[i + 1][(j + 1) % ns], rings[i + 1][j]
            try:
                f = bm.faces.new([a, b, c, d])
                f.smooth = True
            except ValueError:
                pass
    if closed_section:
        for ring in (rings[0], rings[-1]):
            try:
                f = bm.faces.new(ring if ring is rings[-1] else list(reversed(ring)))
                f.smooth = False
            except ValueError:
                pass
        # the winding depends on the section's direction round its loop: make the closed tube face outward
        bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
    bm.normal_update()
    return bm


def bm_transform(bm, xf):
    bmesh.ops.transform(bm, matrix=xf, verts=bm.verts)
    return bm


def mirror_x(bm):
    """Mirror a bmesh across x = 0 (flips winding back)."""
    bmesh.ops.scale(bm, vec=V((-1, 1, 1)), verts=bm.verts)
    bmesh.ops.reverse_faces(bm, faces=bm.faces)
    return bm


def bm_copy(bm):
    out = bm.copy()
    return out


# ------------------------------------------------------------------ surface projection
class Surface:
    """Ray-cast helper over a bmesh (the body), for laying lamps, handles, trims and lettering onto the paint."""

    def __init__(self, bm):
        self.bm = bm.copy()
        bmesh.ops.triangulate(self.bm, faces=self.bm.faces)
        self.bm.normal_update()
        self.tree = BVHTree.FromBMesh(self.bm)

    def hit(self, origin, direction, far=10.0):
        loc, nrm, idx, dist = self.tree.ray_cast(V(origin), V(direction).normalized(), far)
        return loc, nrm

    def frame_at(self, a, b, plane, turn=0.0):
        """For 'auto' decals: hit the surface at (a, b) through the axis plane, then return (point, normal, u, v) with u
        across (horizontal in the surface) and v up the surface. `turn` blends the normal toward the axis direction."""
        h = self.project([(a, b)], plane, 0.0)[0]
        if h is None:
            return None
        loc, n = h
        ax = {'front': V((0, 1, 0)), 'rear': V((0, -1, 0)), 'right': V((1, 0, 0)), 'left': V((-1, 0, 0)), 'top': V((0, 0, 1))}[plane]
        n = (n * (1 - turn) + ax * turn).normalized()
        up = V((0, 0, 1)) if abs(n.z) < 0.9 else V((0, 1, 0))
        u = up.cross(n).normalized()
        a_axis = {'front': V((1, 0, 0)), 'rear': V((1, 0, 0)), 'right': V((0, 1, 0)), 'left': V((0, 1, 0)), 'top': V((1, 0, 0))}[plane]
        if u.dot(a_axis) < 0:
            u = -u
        v = n.cross(u).normalized()
        if v.dot(up) < 0:
            v = -v
        return loc, n, u, v

    def project_frame(self, fr, pts2d, offset=0.0):
        """Project tangent-frame points (du, dv in metres from the frame's point) along -normal."""
        loc, n, u, v = fr
        out = []
        for (du, dv) in pts2d:
            o = loc + u * du + v * dv + n * 0.6
            hl, hn, idx, dist = self.tree.ray_cast(o, -n, 2.0)
            if hl is None:
                out.append(None); continue
            if hn.dot(n) < 0:
                hn = -hn
            out.append((hl + hn * offset, hn))
        return out

    def project(self, pts2d, plane, offset=0.0, depth=None):
        if isinstance(plane, tuple):
            return self.project_frame(plane, pts2d, offset)
        """Project points onto the surface. plane: 'front' (x, z; rays toward -Y from +Y far), 'rear' (x, z; toward +Y),
        'right' (y, z; toward -X from +X), 'left', 'top' (x, y; downward). Returns 3D points pushed `offset` along the normal,
        or None for a miss."""
        out = []
        for (a, b) in pts2d:
            if plane == 'front':
                o, d = V((a, 20, b)), V((0, -1, 0))
            elif plane == 'rear':
                o, d = V((a, -20, b)), V((0, 1, 0))
            elif plane == 'right':
                o, d = V((20, a, b)), V((-1, 0, 0))
            elif plane == 'left':
                o, d = V((-20, a, b)), V((1, 0, 0))
            else:
                o, d = V((a, b, 20)), V((0, 0, -1))
            loc, nrm = self.hit(o, d, 40.0)
            if loc is None:
                out.append(None)
                continue
            if nrm.dot(-d) < 0:
                nrm = -nrm
            out.append((loc + nrm * offset, nrm))
        return out


def grid2d(x0, x1, y0, y1, nx, ny, shape=None):
    """A grid of 2D points; shape(u, v) -> (a, b) may bend it (u, v in 0..1)."""
    pts = []
    for j in range(ny + 1):
        for i in range(nx + 1):
            u, v = i / nx, j / ny
            if shape:
                pts.append(shape(u, v))
            else:
                pts.append((x0 + (x1 - x0) * u, y0 + (y1 - y0) * v))
    return pts


def decal(surface, outline_fn, plane, nx, ny, offset, thick, mat, side_mat=None, rim=True):
    """A conforming panel (lamp lens, plate, trim) laid on the surface: a grid in the projection plane given by
    outline_fn(u, v) -> (a, b), projected, pushed out `offset` (its top) with sides down to `offset - thick`.
    Returns a Part-ready bmesh with material indices 0 (top) and 1 (sides)."""
    pts = [outline_fn(i / nx, j / ny) for j in range(ny + 1) for i in range(nx + 1)]
    hits = surface.project(pts, plane, 0.0)
    if any(h is None for h in hits):
        # drop to what hit; fill misses from neighbours
        good = [h for h in hits if h is not None]
        if not good:
            return None
        hits = [h if h is not None else good[0] for h in hits]
    bm = bmesh.new()
    top = []
    bot = []
    navg = V((0, 0, 0))
    for (loc, nrm) in hits:
        top.append(bm.verts.new(loc + nrm * offset))
        bot.append(bm.verts.new(loc + nrm * (offset - thick)))
        navg += nrm
    navg.normalize()
    W = nx + 1
    for j in range(ny):
        for i in range(nx):
            q = [top[j * W + i], top[j * W + i + 1], top[(j + 1) * W + i + 1], top[(j + 1) * W + i]]
            try:
                f = bm.faces.new(q); f.material_index = 0; f.smooth = True
            except ValueError:
                pass
    if rim:
        edge = [i for i in range(nx + 1)] + [j * W + nx for j in range(1, ny + 1)] + \
               [ny * W + i for i in range(nx - 1, -1, -1)] + [j * W for j in range(ny - 1, 0, -1)]
        for k in range(len(edge)):
            a, b = edge[k], edge[(k + 1) % len(edge)]
            q = [top[a], bot[a], bot[b], top[b]]
            try:
                f = bm.faces.new(q); f.material_index = 1; f.smooth = False
            except ValueError:
                pass
    bm.normal_update()
    orient_decal(bm, navg)
    return bm


def orient_decal(bm, navg):
    """Top faces (material 0) face along navg; side faces face away from the middle."""
    tops = [f for f in bm.faces if f.material_index == 0]
    tot = V((0, 0, 0))
    for f in tops:
        tot += f.normal * f.calc_area()
    if tot.dot(navg) < 0:
        bmesh.ops.reverse_faces(bm, faces=tops)
    cen = V((0, 0, 0))
    for v in bm.verts:
        cen += v.co
    cen /= max(1, len(bm.verts))
    sides = [f for f in bm.faces if f.material_index != 0]
    flip = []
    for f in sides:
        out = f.calc_center_median() - cen
        out -= navg * out.dot(navg)
        if f.normal.dot(out) < 0:
            flip.append(f)
    if flip:
        bmesh.ops.reverse_faces(bm, faces=flip)
    bm.normal_update()


def rounded_rect(cx, cy, w, h, r):
    """outline_fn for a rounded rectangle in the projection plane (u, v in 0..1 over a grid): squash a square grid into the
    rounded rectangle (superellipse)."""
    def fn(u, v):
        x = (u - 0.5) * 2.0
        y = (v - 0.5) * 2.0
        # map the square to a superellipse-ish rounded rectangle
        k = 2.0 + 10.0 * (1.0 - min(r / max(min(w, h) * 0.5, 1e-4), 1.0))
        m = max(abs(x), abs(y))
        if m < 1e-6:
            return (cx, cy)
        n = (abs(x) ** k + abs(y) ** k) ** (1.0 / k)
        s = m / n if n > 1e-9 else 1.0
        return (cx + x * s * w * 0.5, cy + y * s * h * 0.5)
    return fn


def quad_outline(p00, p10, p11, p01):
    """outline_fn for a bilinear quad (four corners in the projection plane)."""
    def fn(u, v):
        a = (p00[0] * (1 - u) + p10[0] * u, p00[1] * (1 - u) + p10[1] * u)
        b = (p01[0] * (1 - u) + p11[0] * u, p01[1] * (1 - u) + p11[1] * u)
        return (a[0] * (1 - v) + b[0] * v, a[1] * (1 - v) + b[1] * v)
    return fn


# ------------------------------------------------------------------ text (fictional lettering) as geometry
def text_bm(txt, size, extrude=0.002, align='CENTER'):
    cu = bpy.data.curves.new("txt", 'FONT')
    cu.body = txt
    cu.size = size
    cu.extrude = extrude
    cu.align_x = align
    cu.align_y = 'CENTER'
    cu.resolution_u = 2
    ob = bpy.data.objects.new("txt", cu)
    bpy.context.scene.collection.objects.link(ob)
    dg = bpy.context.evaluated_depsgraph_get()
    me = bpy.data.meshes.new_from_object(ob.evaluated_get(dg))
    bm = bmesh.new()
    bm.from_mesh(me)
    bpy.data.objects.remove(ob)
    bpy.data.curves.remove(cu)
    bpy.data.meshes.remove(me)
    for f in bm.faces:
        f.smooth = False
    return bm   # in the x-y plane, facing +z


def text_on_side(surface, txt, side, y, z, size, mat, part, offset=0.0025, xscale=1.0):
    """Lettering conformed onto the body side (side +1 right, -1 left), centred at (y, z), reading front to back on the
    left and back to front... (always readable from outside)."""
    bm = text_bm(txt, size, 0.0)
    # letters lie in x-y; map x -> along the car, y -> up
    for v in bm.verts:
        a = v.co.x * xscale
        b = v.co.y
        yy = y + a if side > 0 else y - a
        zz = z + b
        loc, nrm = surface.hit(V((side * 20, yy, zz)), V((-side, 0, 0)), 40)
        if loc is None:
            v.co = V((side * 0.0, yy, zz))
        else:
            v.co = loc + nrm * offset
    if side < 0:
        bmesh.ops.reverse_faces(bm, faces=bm.faces)
    # faces must point outward (+side x)
    bm.normal_update()
    for f in bm.faces:
        if f.normal.x * side < 0:
            f.normal_flip()
    part.add_bm(bm, mat)
    bm.free()


def text_on_plane(txt, size, origin, right, up, mat, part, extrude=0.0):
    bm = text_bm(txt, size, extrude)
    o = V(origin); r = V(right); u = V(up)
    n = r.cross(u)
    for v in bm.verts:
        v.co = o + r * v.co.x + u * v.co.y + n * v.co.z
    bm.normal_update()
    part.add_bm(bm, mat)
    bm.free()


# ------------------------------------------------------------------ utilities
def tri_count(ob):
    me = ob.data
    return sum(len(p.vertices) - 2 for p in me.polygons)


def clear_scene():
    for ob in list(bpy.data.objects):
        bpy.data.objects.remove(ob, do_unlink=True)
    for me in list(bpy.data.meshes):
        bpy.data.meshes.remove(me)
    for a in list(bpy.data.armatures):
        bpy.data.armatures.remove(a)
    for ac in list(bpy.data.actions):
        bpy.data.actions.remove(ac)
    for c in list(bpy.data.collections):
        bpy.data.collections.remove(c)
    for m in list(bpy.data.materials):
        if m.name in MAT_DEFS:
            bpy.data.materials.remove(m)


def box_uv(ob, scale=1.0):
    """Box-projected UVs in metres (u, v = the two coordinates across the face's main axis)."""
    me = ob.data
    if not me.uv_layers:
        me.uv_layers.new(name="UVMap")
    uv = me.uv_layers.active.data
    for p in me.polygons:
        n = p.normal
        ax = max(range(3), key=lambda i: abs(n[i]))
        for li in p.loop_indices:
            co = me.vertices[me.loops[li].vertex_index].co
            if ax == 0:
                uv[li].uv = (co.y * scale * (1 if n.x > 0 else -1), co.z * scale)
            elif ax == 1:
                uv[li].uv = (co.x * scale * (-1 if n.y > 0 else 1), co.z * scale)
            else:
                uv[li].uv = (co.x * scale, co.y * scale)


def smoothstep(a, b, x):
    t = max(0.0, min(1.0, (x - a) / (b - a))) if b != a else (1.0 if x >= b else 0.0)
    return t * t * (3 - 2 * t)


def lerp(a, b, t):
    return a + (b - a) * t


class Fillet:
    """A polyline z(d) with rounded corners: points [(d, z, radius)], d increasing. Evaluate z at any d."""

    def __init__(self, pts, samples=12):
        self.d = []
        self.z = []
        P = [(p[0], p[1]) for p in pts]
        R = [p[2] if len(p) > 2 else 0.0 for p in pts]
        out = [P[0]]
        for i in range(1, len(P) - 1):
            a, b, c = V((P[i - 1][0], P[i - 1][1])), V((P[i][0], P[i][1])), V((P[i + 1][0], P[i + 1][1]))
            r = R[i]
            if r <= 0:
                out.append(P[i]); continue
            u = (a - b).normalized(); w = (c - b).normalized()
            ang = math.acos(max(-1, min(1, u.dot(w))))
            if ang < 1e-3 or ang > math.pi - 1e-3:
                out.append(P[i]); continue
            t = r / math.tan(ang / 2)
            t = min(t, (a - b).length * 0.49, (c - b).length * 0.49)
            r = t * math.tan(ang / 2)
            p1 = b + u * t; p2 = b + w * t
            bis = (u + w).normalized()
            cen = b + bis * (r / math.sin(ang / 2))
            a1 = math.atan2(p1.y - cen.y, p1.x - cen.x)
            a2 = math.atan2(p2.y - cen.y, p2.x - cen.x)
            da = a2 - a1
            while da > math.pi: da -= 2 * math.pi
            while da < -math.pi: da += 2 * math.pi
            for k in range(samples + 1):
                aa = a1 + da * k / samples
                out.append((cen.x + r * math.cos(aa), cen.y + r * math.sin(aa)))
        out.append(P[-1])
        # keep monotone in d
        for (d, z) in out:
            if self.d and d <= self.d[-1]:
                continue
            self.d.append(d); self.z.append(z)

    def __call__(self, d):
        D = self.d
        if d <= D[0]:
            return self.z[0]
        if d >= D[-1]:
            return self.z[-1]
        lo, hi = 0, len(D) - 1
        while hi - lo > 1:
            m = (lo + hi) // 2
            if D[m] <= d: lo = m
            else: hi = m
        t = (d - D[lo]) / (D[hi] - D[lo])
        return self.z[lo] + (self.z[hi] - self.z[lo]) * t
